/**
 * Marked.js - Complete GFM-compatible Markdown Parser
 * Version: 1.0.0 (Custom Implementation)
 * Supports: GFM, tables, code blocks, task lists, strikethrough, and more
 */
var marked = (function() {
    'use strict';

    // Configuration options
    let options = {
        breaks: true,
        gfm: true,
        headerIds: true,
        mangle: false,
        pedantic: false,
        sanitize: false,
        smartLists: true,
        smartypants: false,
        xhtml: false
    };

    // Helper functions
    function escapeHtml(text) {
        if (!text) return '';
        const map = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#39;'
        };
        return String(text).replace(/[&<>"']/g, m => map[m]);
    }

    function generateId(text) {
        return text.toLowerCase()
            .replace(/[^\w\s-]/g, '')
            .replace(/\s+/g, '-')
            .replace(/-+/g, '-')
            .trim();
    }

    // Token types
    const BLOCK_TOKENS = {
        FENCED_CODE: /^(`{3,}|~{3,})([^\n]*)\n([\s\S]*?)\1/,
        INDENTED_CODE: /^(?: {4}[^\n]*\n?)+/,
        HEADING: /^(#{1,6})\s+(.+?)(?:\s+#*)?$/,
        HORIZONTAL_RULE: /^(?:[-*_]){3,}\s*$/,
        BLOCKQUOTE: /^>\s?/,
        UNORDERED_LIST: /^([\s]*)[-*+]\s+/,
        ORDERED_LIST: /^([\s]*)(\d+)\.\s+/,
        TASK_LIST_ITEM: /^\[([ xX])\]\s+/,
        TABLE_HEADER: /^\|(.+)\|\s*$/,
        TABLE_SEPARATOR: /^\|(?:\s*:?-+:?\s*\|)+\s*$/,
        TABLE_ROW: /^\|(.+)\|\s*$/,
        EMPTY_LINE: /^\s*$/
    };

    // Parse fenced code blocks
    function parseFencedCode(text) {
        const blocks = [];
        let remaining = text;
        
        while (remaining) {
            const match = remaining.match(/^(`{3,}|~{3,})([^\n]*)\n([\s\S]*?)\1/m);
            if (match && remaining.indexOf(match[0]) === 0) {
                const lang = match[2].trim();
                const code = match[3];
                blocks.push({
                    type: 'code',
                    lang: lang,
                    code: code,
                    raw: match[0]
                });
                remaining = remaining.slice(match[0].length);
            } else {
                // Find next code block or end
                const nextMatch = remaining.slice(1).match(/^(`{3,}|~{3,})/m);
                if (nextMatch) {
                    const idx = remaining.indexOf(nextMatch[0], 1);
                    blocks.push({
                        type: 'text',
                        content: remaining.slice(0, idx)
                    });
                    remaining = remaining.slice(idx);
                } else {
                    blocks.push({
                        type: 'text',
                        content: remaining
                    });
                    break;
                }
            }
        }
        
        return blocks;
    }

    // Parse tables
    function parseTable(lines) {
        if (lines.length < 2) return null;
        
        // Check for table separator
        const sepMatch = lines[1].match(/^\|(?:\s*:?-+:?\s*\|)+\s*$/);
        if (!sepMatch) return null;
        
        // Parse header
        const headerCells = lines[0].slice(1, -1).split('|').map(c => c.trim());
        
        // Parse alignment
        const alignments = lines[1].slice(1, -1).split('|').map(c => {
            c = c.trim();
            if (c.startsWith(':') && c.endsWith(':')) return 'center';
            if (c.endsWith(':')) return 'right';
            return 'left';
        });
        
        // Parse rows
        const rows = [];
        for (let i = 2; i < lines.length; i++) {
            if (!lines[i].match(/^\|(.+)\|\s*$/)) break;
            const cells = lines[i].slice(1, -1).split('|').map(c => c.trim());
            rows.push(cells);
        }
        
        return {
            headers: headerCells,
            alignments: alignments,
            rows: rows,
            rowCount: rows.length + 2
        };
    }

    // Render table to HTML
    function renderTable(table) {
        let html = '<table>\n<thead>\n<tr>\n';
        
        table.headers.forEach((header, i) => {
            const align = table.alignments[i] || 'left';
            html += `<th style="text-align: ${align}">${parseInline(header)}</th>\n`;
        });
        
        html += '</tr>\n</thead>\n<tbody>\n';
        
        table.rows.forEach(row => {
            html += '<tr>\n';
            row.forEach((cell, i) => {
                const align = table.alignments[i] || 'left';
                html += `<td style="text-align: ${align}">${parseInline(cell)}</td>\n`;
            });
            html += '</tr>\n';
        });
        
        html += '</tbody>\n</table>\n';
        return html;
    }

    // Parse inline elements
    function parseInline(text) {
        if (!text) return '';
        
        let result = text;
        
        // Escape HTML first (but preserve already escaped)
        result = result.replace(/&(?!(?:amp|lt|gt|quot|#39);)/g, '&amp;');
        result = result.replace(/<(?![^<>]*>)/g, '&lt;');
        result = result.replace(/(?<![^<>]*)>/g, '&gt;');
        
        // Images (before links to avoid conflict)
        result = result.replace(/!\[([^\]]*)\]\(([^)\s]+)(?:\s+"([^"]*)")?\)/g, 
            (match, alt, src, title) => {
                const titleAttr = title ? ` title="${escapeHtml(title)}"` : '';
                return `<img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}"${titleAttr} />`;
            });
        
        // Links with title
        result = result.replace(/\[([^\]]+)\]\(([^)\s]+)(?:\s+"([^"]*)")?\)/g, 
            (match, text, href, title) => {
                const titleAttr = title ? ` title="${escapeHtml(title)}"` : '';
                return `<a href="${escapeHtml(href)}"${titleAttr}>${text}</a>`;
            });
        
        // Autolinks
        result = result.replace(/<(https?:\/\/[^>]+)>/g, '<a href="$1">$1</a>');
        result = result.replace(/<([^@\s>]+@[^>]+)>/g, '<a href="mailto:$1">$1</a>');
        
        // Inline code (must be before other formatting)
        result = result.replace(/`([^`]+)`/g, '<code>$1</code>');
        
        // Bold and italic combined
        result = result.replace(/\*\*\*([^*]+)\*\*\*/g, '<strong><em>$1</em></strong>');
        result = result.replace(/___([^_]+)___/g, '<strong><em>$1</em></strong>');
        
        // Bold
        result = result.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
        result = result.replace(/__([^_]+)__/g, '<strong>$1</strong>');
        
        // Italic
        result = result.replace(/\*([^*]+)\*/g, '<em>$1</em>');
        result = result.replace(/_([^_\s][^_]*)_/g, '<em>$1</em>');
        
        // Strikethrough (GFM)
        result = result.replace(/~~([^~]+)~~/g, '<del>$1</del>');
        
        // Highlighted text
        result = result.replace(/==([^=]+)==/g, '<mark>$1</mark>');
        
        // Subscript
        result = result.replace(/~([^~\s]+)~/g, '<sub>$1</sub>');
        
        // Superscript
        result = result.replace(/\^([^\^\s]+)\^/g, '<sup>$1</sup>');
        
        return result;
    }

    // Parse blockquotes
    function parseBlockquote(lines) {
        const content = lines.map(line => line.replace(/^>\s?/, '')).join('\n');
        return '<blockquote>\n' + parse(content) + '</blockquote>\n';
    }

    // Parse list with nested list support
    function parseList(lines, ordered) {
        const tag = ordered ? 'ol' : 'ul';
        let html = `<${tag}>\n`;
        
        let i = 0;
        while (i < lines.length) {
            const line = lines[i];
            
            // Get the indentation level of current line
            const indentMatch = line.match(/^(\s*)/);
            const currentIndent = indentMatch ? indentMatch[1].length : 0;
            
            // Check if it's a list item
            const unorderedMatch = line.match(/^(\s*)[-*+]\s+(.*)$/);
            const orderedMatch = line.match(/^(\s*)(\d+)\.\s+(.*)$/);
            
            if ((ordered && orderedMatch) || (!ordered && unorderedMatch)) {
                const itemContent = ordered ? orderedMatch[3] : unorderedMatch[2];
                const itemIndent = ordered ? orderedMatch[1].length : unorderedMatch[1].length;
                
                // Check for task list item
                const taskMatch = itemContent.match(/^\[([ xX])\]\s+(.*)$/);
                
                // Look ahead for nested items
                let nestedLines = [];
                let j = i + 1;
                while (j < lines.length) {
                    const nextLine = lines[j];
                    const nextIndentMatch = nextLine.match(/^(\s*)/);
                    const nextIndent = nextIndentMatch ? nextIndentMatch[1].length : 0;
                    
                    // Check if next line is a nested list item (more indented)
                    if (nextIndent > itemIndent && (nextLine.match(/^\s*[-*+]\s+/) || nextLine.match(/^\s*\d+\.\s+/))) {
                        nestedLines.push(nextLine);
                        j++;
                    } else if (nextIndent > itemIndent && nextLine.trim()) {
                        // Continuation of current item
                        nestedLines.push(nextLine);
                        j++;
                    } else {
                        break;
                    }
                }
                
                // Build the list item
                if (taskMatch) {
                    const checked = taskMatch[1].toLowerCase() === 'x' ? ' checked' : '';
                    html += `<li class="task-list-item"><input type="checkbox"${checked} disabled /> ${parseInline(taskMatch[2])}`;
                } else {
                    html += `<li>${parseInline(itemContent)}`;
                }
                
                // Process nested content
                if (nestedLines.length > 0) {
                    // Check if nested content is a list
                    const firstNestedLine = nestedLines[0];
                    const isNestedUnordered = firstNestedLine.match(/^\s*[-*+]\s+/);
                    const isNestedOrdered = firstNestedLine.match(/^\s*\d+\.\s+/);
                    
                    if (isNestedUnordered || isNestedOrdered) {
                        // Remove base indentation from nested lines
                        const baseIndent = nestedLines[0].match(/^(\s*)/)[1].length;
                        const normalizedLines = nestedLines.map(l => l.slice(Math.min(baseIndent, l.match(/^(\s*)/)[1].length)));
                        html += '\n' + parseList(normalizedLines, !!isNestedOrdered);
                    }
                }
                
                html += `</li>\n`;
                i = j;
            } else {
                i++;
            }
        }
        
        html += `</${tag}>\n`;
        return html;
    }

    // Main parse function
    function parse(markdown) {
        if (!markdown) return '';
        
        let html = '';
        
        // First, handle fenced code blocks to protect them
        const blocks = parseFencedCode(markdown);
        
        for (const block of blocks) {
            if (block.type === 'code') {
                const langClass = block.lang ? ` class="language-${escapeHtml(block.lang)}"` : '';
                html += `<pre><code${langClass}>${escapeHtml(block.code)}</code></pre>\n`;
            } else {
                html += parseBlocks(block.content);
            }
        }
        
        return html;
    }

    // Parse block-level content
    function parseBlocks(text) {
        if (!text) return '';
        
        const lines = text.split('\n');
        let html = '';
        let i = 0;
        let inParagraph = false;
        let paragraphContent = '';
        
        function closeParagraph() {
            if (inParagraph && paragraphContent.trim()) {
                html += '<p>' + parseInline(paragraphContent.trim()) + '</p>\n';
                paragraphContent = '';
                inParagraph = false;
            }
        }
        
        while (i < lines.length) {
            const line = lines[i];
            
            // Empty line
            if (BLOCK_TOKENS.EMPTY_LINE.test(line)) {
                closeParagraph();
                i++;
                continue;
            }
            
            // Indented code block
            if (line.match(/^ {4}/) || line.match(/^\t/)) {
                closeParagraph();
                const codeLines = [];
                while (i < lines.length && (lines[i].match(/^ {4}/) || lines[i].match(/^\t/) || lines[i].match(/^\s*$/))) {
                    codeLines.push(lines[i].replace(/^ {4}/, '').replace(/^\t/, ''));
                    i++;
                }
                html += `<pre><code>${escapeHtml(codeLines.join('\n').trim())}</code></pre>\n`;
                continue;
            }
            
            // Heading
            const headingMatch = line.match(BLOCK_TOKENS.HEADING);
            if (headingMatch) {
                closeParagraph();
                const level = headingMatch[1].length;
                const content = headingMatch[2].trim();
                const id = options.headerIds ? ` id="${generateId(content)}"` : '';
                html += `<h${level}${id}>${parseInline(content)}</h${level}>\n`;
                i++;
                continue;
            }
            
            // Horizontal rule
            if (BLOCK_TOKENS.HORIZONTAL_RULE.test(line)) {
                closeParagraph();
                html += '<hr />\n';
                i++;
                continue;
            }
            
            // Blockquote
            if (line.match(BLOCK_TOKENS.BLOCKQUOTE)) {
                closeParagraph();
                const quoteLines = [];
                while (i < lines.length && (lines[i].match(/^>\s?/) || (lines[i].trim() && !lines[i].match(/^\s*$/)))) {
                    if (lines[i].match(/^>\s?/)) {
                        quoteLines.push(lines[i]);
                        i++;
                    } else if (quoteLines.length > 0 && lines[i].trim()) {
                        quoteLines.push('> ' + lines[i]);
                        i++;
                    } else {
                        break;
                    }
                }
                html += parseBlockquote(quoteLines);
                continue;
            }
            
            // Table
            if (line.match(BLOCK_TOKENS.TABLE_HEADER) && i + 1 < lines.length && lines[i + 1].match(BLOCK_TOKENS.TABLE_SEPARATOR)) {
                closeParagraph();
                const tableLines = [];
                while (i < lines.length && lines[i].match(/^\|/)) {
                    tableLines.push(lines[i]);
                    i++;
                }
                const table = parseTable(tableLines);
                if (table) {
                    html += renderTable(table);
                }
                continue;
            }
            
            // Unordered list
            if (line.match(BLOCK_TOKENS.UNORDERED_LIST)) {
                closeParagraph();
                const listLines = [];
                while (i < lines.length) {
                    const currentLine = lines[i];
                    // Match list items or indented content (for nested lists)
                    if (currentLine.match(/^(\s*)[-*+]\s+/) || 
                        (listLines.length > 0 && currentLine.match(/^\s+/) && currentLine.trim())) {
                        listLines.push(currentLine);
                        i++;
                    } else if (currentLine.match(/^\s*$/) && listLines.length > 0 && i + 1 < lines.length && lines[i + 1].match(/^\s+[-*+]\s+/)) {
                        // Allow empty line if next line is nested list item
                        i++;
                    } else {
                        break;
                    }
                }
                html += parseList(listLines, false);
                continue;
            }
            
            // Ordered list
            if (line.match(BLOCK_TOKENS.ORDERED_LIST)) {
                closeParagraph();
                const listLines = [];
                while (i < lines.length) {
                    const currentLine = lines[i];
                    // Match list items or indented content (for nested lists)
                    if (currentLine.match(/^(\s*)\d+\.\s+/) || 
                        (listLines.length > 0 && currentLine.match(/^\s+/) && currentLine.trim())) {
                        listLines.push(currentLine);
                        i++;
                    } else if (currentLine.match(/^\s*$/) && listLines.length > 0 && i + 1 < lines.length && lines[i + 1].match(/^\s+\d+\.\s+/)) {
                        // Allow empty line if next line is nested list item
                        i++;
                    } else {
                        break;
                    }
                }
                html += parseList(listLines, true);
                continue;
            }
            
            // Regular paragraph content
            if (!inParagraph) {
                inParagraph = true;
                paragraphContent = line;
            } else {
                if (options.breaks) {
                    paragraphContent += '<br />\n' + line;
                } else {
                    paragraphContent += '\n' + line;
                }
            }
            i++;
        }
        
        closeParagraph();
        return html;
    }

    // Set options
    function setOptions(opts) {
        if (opts) {
            Object.assign(options, opts);
        }
    }

    // Get options
    function getDefaults() {
        return { ...options };
    }

    return {
        parse: parse,
        setOptions: setOptions,
        getDefaults: getDefaults,
        // Aliases for compatibility
        marked: parse,
        parseInline: parseInline
    };
})();

// For compatibility with different module systems
if (typeof module !== 'undefined' && module.exports) {
    module.exports = marked;
}
